/**
 * emit to subscription queries of type FindApproval,
 * but only if the id matches
 *
 * @param		entity	Approval
 */
	protected void emitFindApproval( Approval entity ) {
		LOGGER.info("handling emitFindApproval" );
		
	    queryUpdateEmitter.emit(FindApprovalQuery.class,
	                            query -> query.getFilter().getApprovalId().equals(entity.getApprovalId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllApproval
	 * 
	 * @param		entity	Approval
	 */
	protected void emitFindAllApproval( Approval entity ) {
		LOGGER.info("handling emitFindAllApproval" );
		
	    queryUpdateEmitter.emit(FindAllApprovalQuery.class,
	                            query -> true,
	                            entity);
	}

